CREATE TABLE IF NOT EXISTS `interview_evaluations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `interview_id` bigint(20) unsigned NOT NULL,
  `technical_score` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `problem_solving_score` tinyint(3) unsigned NOT NULL DEFAULT 4,
  `communication_score` tinyint(3) unsigned NOT NULL DEFAULT 5,
  `culture_score` tinyint(3) unsigned NOT NULL DEFAULT 5,
  `overall_score` decimal(3,2) GENERATED ALWAYS AS ((`technical_score` + `problem_solving_score` + `communication_score` + `culture_score`) / 4.0) STORED,
  `overall_recommendation` enum('strong_hire','hire','hold','reject') NOT NULL DEFAULT 'hire',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `interview_id` (`interview_id`),
  KEY `idx_eval_recommendation` (`overall_recommendation`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

