  `last_message_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_thread_participants` (`employer_id`,`candidate_id`),
  KEY `idx_thread_last_message` (`last_message_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `migrations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `migration` varchar(255) NOT NULL,
  `batch` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `newsletter_campaigns` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `subject` varchar(200) NOT NULL,
  `preheader` varchar(200) DEFAULT NULL,
  `title` varchar(200) NOT NULL,
  `hero` varchar(40) DEFAULT NULL,
  `body` mediumtext NOT NULL,
  `cta_label` varchar(60) DEFAULT NULL,
  `cta_url` varchar(500) DEFAULT NULL,
  `jenny_tip` varchar(600) DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'draft',
  `recipients` int(10) unsigned NOT NULL DEFAULT 0,
  `created_by` varchar(120) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `queued_at` datetime DEFAULT NULL,
  `type` varchar(16) NOT NULL DEFAULT 'general',
  `audience` varchar(16) NOT NULL DEFAULT 'all',
  `hero_url` varchar(500) DEFAULT NULL,
  `body_image_url` varchar(500) DEFAULT NULL,
  `extra` text DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `newsletter_subscribers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(190) NOT NULL,
  `name` varchar(120) DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'pending',
  `source` varchar(40) NOT NULL DEFAULT 'website',
  `token` char(40) NOT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `unsubscribed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `audience` varchar(16) NOT NULL DEFAULT 'student',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_newsletter_email` (`email`),
  UNIQUE KEY `uq_newsletter_token` (`token`),
  KEY `idx_newsletter_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `partner_applications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `partner_id` bigint(20) unsigned NOT NULL,
  `candidate_id` bigint(20) unsigned NOT NULL,
  `reference` varchar(24) NOT NULL,
  `program` varchar(160) DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'started',
  `status_at` datetime NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pa_reference` (`reference`),
  KEY `idx_pa_candidate` (`candidate_id`,`partner_id`),
  KEY `idx_pa_partner` (`partner_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `partner_idempotency` (
  `partner_id` bigint(20) unsigned NOT NULL,
  `idem_key` varchar(80) NOT NULL,
  `request_hash` char(64) NOT NULL,
  `status` smallint(5) unsigned NOT NULL,
  `response` mediumtext NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`partner_id`,`idem_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `password_reset_tokens` (
  `email` varchar(255) NOT NULL,
  `token` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `plan_features` (
  `feature_key` varchar(40) NOT NULL,
  `plan` varchar(16) NOT NULL,
  `value` varchar(120) NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`feature_key`,`plan`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `plan_grants` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `account_type` varchar(16) NOT NULL,
  `account_id` bigint(20) unsigned NOT NULL,
  `plan` varchar(16) NOT NULL,
  `source` varchar(40) NOT NULL,
  `source_ref` varchar(80) DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `starts_at` datetime NOT NULL,
  `expires_at` datetime NOT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'active',
  `created_by` varchar(80) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pg_account` (`account_type`,`account_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `plan_reminders` (
  `account_type` varchar(16) NOT NULL,
  `account_id` bigint(20) unsigned NOT NULL,
  `period_end` datetime NOT NULL,
  `sent_at` datetime NOT NULL,
  PRIMARY KEY (`account_type`,`account_id`,`period_end`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `plan_settings` (
  `setting_key` varchar(60) NOT NULL,
  `setting_value` varchar(255) NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `platform_settings` (
  `setting_key` varchar(100) NOT NULL,
  `setting_value` text NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `rate_limits` (
  `bucket` char(64) NOT NULL,
  `window_start` int(10) unsigned NOT NULL,
  `hits` int(10) unsigned NOT NULL,
  PRIMARY KEY (`bucket`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `saved_internships` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `internship_id` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `saved_internships_user_id_foreign` (`user_id`),
  KEY `saved_internships_internship_id_foreign` (`internship_id`),
  CONSTRAINT `saved_internships_internship_id_foreign` FOREIGN KEY (`internship_id`) REFERENCES `internships` (`id`) ON DELETE CASCADE,
  CONSTRAINT `saved_internships_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `scheduled_interviews` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `candidate_id` bigint(20) unsigned NOT NULL DEFAULT 1,
  `employer_id` bigint(20) unsigned NOT NULL DEFAULT 1,
  `candidate_name` varchar(150) NOT NULL,
  `candidate_role` varchar(150) NOT NULL,
  `company_name` varchar(150) NOT NULL,
  `interviewer_name` varchar(150) NOT NULL,
  `meeting_type` varchar(20) NOT NULL DEFAULT 'virtual',
  `meeting_link` varchar(500) NOT NULL DEFAULT '',
  `interview_date` varchar(20) NOT NULL,
  `interview_time` varchar(20) NOT NULL,
  `duration` varchar(20) NOT NULL DEFAULT '30 mins',
  `status` varchar(20) NOT NULL DEFAULT 'Scheduled',
  `notes` text DEFAULT NULL,
  `scheduled_at` datetime DEFAULT NULL,
  `duration_min` smallint(5) unsigned DEFAULT NULL,
  `setup_json` text DEFAULT NULL COMMENT 'Employer criteria, questions and decision options',
  `created_by` varchar(20) DEFAULT NULL COMMENT 'employer | admin (NULL = legacy row, hidden from lists)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_sched_employer` (`employer_id`,`scheduled_at`),
  KEY `idx_sched_candidate` (`candidate_id`,`scheduled_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `sessions` (
  `id` varchar(255) NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `payload` longtext NOT NULL,
  `last_activity` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `sessions_user_id_index` (`user_id`),
  KEY `sessions_last_activity_index` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `testimonials` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kind` varchar(10) NOT NULL DEFAULT 'quote',
  `name` varchar(120) NOT NULL,
  `handle` varchar(120) DEFAULT NULL,
  `role` varchar(160) DEFAULT NULL,
  `quote` text DEFAULT NULL,
  `platform` varchar(20) NOT NULL DEFAULT 'linkedin',
  `source_url` varchar(500) DEFAULT NULL,
  `avatar_url` varchar(500) DEFAULT NULL,
  `video_url` varchar(500) DEFAULT NULL,
  `rating` tinyint(3) unsigned DEFAULT NULL,
  `audience` varchar(16) NOT NULL DEFAULT 'student',
  `show_home` tinyint(1) NOT NULL DEFAULT 1,
  `show_page` tinyint(1) NOT NULL DEFAULT 1,
  `sort` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_testimonials_live` (`is_active`,`kind`,`sort`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `tier_rules` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `partner_id` bigint(20) unsigned DEFAULT NULL,
  `min_score` decimal(5,2) NOT NULL,
  `max_score` decimal(5,2) NOT NULL,
  `plan` varchar(16) NOT NULL,
  `duration_days` int(10) unsigned NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tier_partner` (`partner_id`,`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `training_partners` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(60) NOT NULL,
  `name` varchar(120) NOT NULL,
  `website` varchar(255) DEFAULT NULL,
  `application_url` varchar(500) DEFAULT NULL,
  `contact_email` varchar(190) DEFAULT NULL,
  `elearning_partner_id` bigint(20) unsigned DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'active',
  `pass_mark` decimal(5,2) NOT NULL DEFAULT 50.00,
  `application_days` int(10) unsigned NOT NULL DEFAULT 120,
  `api_key_prefix` varchar(16) DEFAULT NULL,
  `api_key_hash` char(64) DEFAULT NULL,
  `signing_secret_enc` text DEFAULT NULL,
  `key_rotated_at` datetime DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tp_slug` (`slug`),
  UNIQUE KEY `uq_tp_prefix` (`api_key_prefix`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `training_results` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `partner_id` bigint(20) unsigned NOT NULL,
  `application_id` bigint(20) unsigned NOT NULL,
  `candidate_id` bigint(20) unsigned NOT NULL,
  `reference` varchar(24) NOT NULL,
  `score` decimal(5,2) NOT NULL,
  `passed` tinyint(1) NOT NULL,
  `course` varchar(160) DEFAULT NULL,
  `certificate_id` varchar(80) DEFAULT NULL,
  `certificate_url` varchar(500) DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'active',
  `supersedes_id` bigint(20) unsigned DEFAULT NULL,
  `rule_id` bigint(20) unsigned DEFAULT NULL,
  `grant_id` bigint(20) unsigned DEFAULT NULL,
  `plan` varchar(16) DEFAULT NULL,
  `plan_days` int(10) unsigned DEFAULT NULL,
  `source` varchar(16) NOT NULL DEFAULT 'api',
  `created_by` varchar(120) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tr_candidate` (`candidate_id`,`status`),
  KEY `idx_tr_application` (`application_id`,`status`),
  KEY `idx_tr_partner` (`partner_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `usage_counters` (
  `account_type` varchar(16) NOT NULL,
  `account_id` bigint(20) unsigned NOT NULL,
  `feature_key` varchar(40) NOT NULL,
  `period_key` varchar(16) NOT NULL,
  `used` int(10) unsigned NOT NULL DEFAULT 0,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`account_type`,`account_id`,`feature_key`,`period_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `role` enum('candidate','employer','admin') NOT NULL DEFAULT 'candidate',
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `visit_sessions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `session_key` char(64) NOT NULL,
  `visitor_key` char(64) DEFAULT NULL,
  `role` varchar(16) NOT NULL DEFAULT 'visitor',
  `ip_masked` varchar(45) DEFAULT NULL,
  `city` varchar(80) DEFAULT NULL,
  `country` varchar(80) DEFAULT NULL,
  `country_code` char(2) DEFAULT NULL,
  `lat` decimal(9,5) DEFAULT NULL,
  `lng` decimal(9,5) DEFAULT NULL,
  `device` varchar(60) DEFAULT NULL,
  `page` varchar(200) DEFAULT NULL,
  `pages` int(10) unsigned NOT NULL DEFAULT 1,
  `first_seen` datetime NOT NULL,
  `last_seen` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_visit_session` (`session_key`),
  KEY `idx_visit_last` (`last_seen`),
  KEY `idx_visit_visitor` (`visitor_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
